import { describe, expect, it, vi } from "vitest";
import { ja } from "../strings/ja";
import { CommandRegistry, createCommandRegistry } from "./registry";
import type {
  Command,
  CommandContext,
  CommandSnapshot,
} from "./types";

const SNAPSHOT_EMPTY: CommandSnapshot = {
  hasAudio: false,
  hasScore: false,
  isTranscribing: false,
  isPlaying: false,
  loopEnabled: false,
  pitch: "concert",
  canUndo: false,
  canRedo: false,
  hasSelection: false,
  hasWaveformSelection: false,
  reviewOpen: false,
  reviewCount: 0,
      isRecording: false,
      isRecordingPaused: false,
      auditionEnabled: false,
  view: "workspace",
};

const SNAPSHOT_SCORE: CommandSnapshot = {
  ...SNAPSHOT_EMPTY,
  hasAudio: true,
  hasScore: true,
  canUndo: true,
  canRedo: true,
  hasSelection: true,
  reviewCount: 3,
      isRecording: false,
      isRecordingPaused: false,
      auditionEnabled: false,
};

function mockContext(): CommandContext & { calls: string[] } {
  const calls: string[] = [];
  const spy = (name: string) => vi.fn(() => calls.push(name));
  return {
    calls,
    openAudio: spy("openAudio"),
    transcribe: spy("transcribe"),
    togglePlayPause: spy("togglePlayPause"),
    stop: spy("stop"),
