/**
 * #115 (GUI_UX_SPEC §13): rhythm edits that re-realize notation through
 * the engine's score.edit method.
 *
 * Pitch/delete/respell edits rewrite MusicXML client-side; the three
 * timing edits (duration change, onset grid shift, tie toggle) change
 * the canonical payload, so the engine re-decomposes the affected
 * measures with the same SpanRealizer the quantizer used and returns
 * fresh MusicXML + a new scoreRevision (content-derived).
 *
 * The desktop keeps the edit on the shared undo stack by snapshotting
 * the document's XML bodies before the call and swapping them back on
 * undo — see ReviewSession.commitDocSwap.
 */

/** Edit kinds the engine's score.edit accepts (transcription/scoreedit.py). */
export type RhythmEditKind = "setDuration" | "shiftOnset" | "toggleTie";

/** One rhythm edit request — mirrors ScoreEdit.from_dict on the engine. */
export interface RhythmEditOp {
  readonly kind: RhythmEditKind;
  /** Canonical `sn-*` note id. */
  readonly noteId: string;
  /** setDuration only: new written length as a "n/d" beat fraction. */
  readonly durationBeats?: string;
  /** shiftOnset only: signed count of minimum-grid steps. */
  readonly steps?: number;
}

/** What score.edit returns — the rebuilt canonical payload + fresh XML. */
export interface ScoreEditResult {
  readonly scoreDocument: unknown;
  readonly scoreRevision: string;
  readonly musicXmlConcert: string;
  readonly musicXmlHornF: string;
}

/** The engine call the workspace delegates to (session.applyScoreEdit). */
export type RhythmEditInvoker = (
  scoreDocument: unknown,
  op: RhythmEditOp,
) => Promise<ScoreEditResult>;

/** A reduced "n/d" beat fraction (the canonical payload's wire form). */
export interface BeatFraction {
  readonly num: number;
  readonly den: number;
}

function gcd(a: number, b: number): number {
  let x = Math.abs(a);
  let y = Math.abs(b);
  while (y !== 0) {
    const t = y;
    y = x % y;
    x = t;
  }
  return x || 1;
}

/** Parse a "n/d" beat fraction; null when the shape is not a fraction. */
export function parseFraction(raw: unknown): BeatFraction | null {
  if (typeof raw !== "string") return null;
  const m = /^(-?\d+)\/(\d+)$/.exec(raw.trim());
  if (!m) return null;
  const num = Number(m[1]);
  const den = Number(m[2]);
  if (!Number.isSafeInteger(num) || !Number.isSafeInteger(den) || den <= 0) {
    return null;
  }
  const g = gcd(num, den);
  return { num: num / g, den: den / g };
}

/** Serialize back to the canonical "n/d" wire form. */
export function formatFraction(f: BeatFraction): string {
  return `${f.num}/${f.den}`;
}

/**
 * Scale a beat fraction by 2^power (power ∈ {-1, +1} for the duration
 * ladder). Returns null when the result would leave the safe-integer
 * range — the caller treats that as "cannot apply", never clamps.
 */
export function scaleFraction(
  f: BeatFraction,
  power: number,
): BeatFraction | null {
  let { num, den } = f;
  if (power > 0) {
    // ×2 per step: halve the denominator when possible, else double
    // the numerator — the fraction stays exact.
    for (let i = 0; i < power; i += 1) {
      if (den % 2 === 0) den /= 2;
      else num *= 2;
      if (!Number.isSafeInteger(num) || !Number.isSafeInteger(den)) {
        return null;
      }
    }
  } else {
    // ÷2 per step.
    for (let i = 0; i < -power; i += 1) {
      if (num % 2 === 0) num /= 2;
      else den *= 2;
      if (!Number.isSafeInteger(num) || !Number.isSafeInteger(den)) {
        return null;
      }
    }
  }
  const g = gcd(num, den);
  return { num: num / g, den: den / g };
}

/** What a duration/onset edit needs to know about the target note. */
export interface CanonicalNoteTiming {
  readonly noteId: string;
  readonly startBeat: BeatFraction;
  readonly durationBeats: BeatFraction;
  readonly pitchMidi: number;
}

/**
 * Find one canonical note inside a scoreDocument dict (schema v1:
 * `{ content: { parts: [{ notes: [...] }] } }`). Returns null when the
 * document or the note is missing — callers treat that as "cannot edit"
 * rather than guessing.
 */
export function findCanonicalNote(
  scoreDocument: unknown,
  noteId: string,
): CanonicalNoteTiming | null {
  if (typeof scoreDocument !== "object" || scoreDocument === null) {
    return null;
  }
  const content = (scoreDocument as Record<string, unknown>).content;
  if (typeof content !== "object" || content === null) return null;
  const parts = (content as Record<string, unknown>).parts;
  if (!Array.isArray(parts)) return null;
  for (const part of parts) {
    if (typeof part !== "object" || part === null) continue;
    const notes = (part as Record<string, unknown>).notes;
    if (!Array.isArray(notes)) continue;
    for (const note of notes) {
      if (typeof note !== "object" || note === null) continue;
      const n = note as Record<string, unknown>;
      if (n.id !== noteId) continue;
      const startBeat = parseFraction(n.startBeat);
      const durationBeats = parseFraction(n.durationBeats);
      const pitchMidi =
        typeof n.pitchMidi === "number" ? n.pitchMidi : null;
      if (!startBeat || !durationBeats || pitchMidi === null) return null;
      return { noteId, startBeat, durationBeats, pitchMidi };
    }
  }
  return null;
}

/**
 * XmlScoreDocument — `ScoreDocumentPort` over arbitrary MusicXML bodies
 * (ENG-002).
 *
 * The fixture adapter proved the contract; this is the general form the
 * real engine result slots into: the transcription job returns
 * `musicXmlConcert` + `musicXmlHornF` (same canonical `hs-sn-*` ids in
 * both — the export layer's contract), the `sr-*` revision id, and the
 * typed review issues. Review decisions and note edits live here, keyed
 * to `revisionId` — a new score revision constructs a fresh document,
 * so stale decisions are never carried across (domain/review.py rule).
 */
import type { PitchViewSetting } from "../commands/types";
import type { ScoreDocumentMeta, ScoreDocumentPort } from "./document";
import { parseScoreDoc } from "./scoreDoc";
import type { ReviewIssueStatus, ScoreReviewIssue } from "./review";
import {
  applyNoteEdits,
  isEmptyNoteEdit,
  type ScoreNoteEdit,
} from "./scoreEdits";

export interface XmlScoreDocumentSources {
  /** Canonical sounding-pitch MusicXML (`<sound tempo>` etc. drive meta). */
  readonly concertXml: string;
  /** Written-pitch F管 presentation of the SAME canonical notes. */
  readonly hornXml: string;
  /** `sr-*`/`rev-*` revision id the decisions/edits bind to. */
  readonly revisionId: string;
  /** Engine review issues for this revision (`[]` = honestly clean). */
  readonly issues: readonly ScoreReviewIssue[];
  /** #115: canonical scoreDocument dict — the base the engine's
   *  `score.edit` re-realizes from (undefined for fixture/dev). */
  readonly canonicalDocument?: unknown;
}

export class XmlScoreDocument implements ScoreDocumentPort {
  private _revisionId: string;
  private _meta: ScoreDocumentMeta;
  private concertXml: string;
  private hornXml: string;
  private canonicalDoc: unknown | null;
  private readonly issues: readonly ScoreReviewIssue[];
  private readonly decisions = new Map<string, ReviewIssueStatus>();
  private readonly edits = new Map<string, ScoreNoteEdit>();
  private editCounter = 0;

  constructor(src: XmlScoreDocumentSources) {
    this._revisionId = src.revisionId;
    this.issues = src.issues;
    this.concertXml = src.concertXml;
    this.hornXml = src.hornXml;
    this.canonicalDoc = src.canonicalDocument ?? null;
    this._meta = XmlScoreDocument.computeMeta(src.concertXml);
  }

  private static computeMeta(xml: string): ScoreDocumentMeta {
    const doc = parseScoreDoc(xml);
    const canonical = new Set(
      doc.notes.map((n) => n.canonicalId).filter(Boolean),
    );
    return {
      title: doc.title,
      tempoBpm: doc.tempoBpm,
      meter: doc.meter,
      keyFifths: doc.keyFifths,
      measureCount: doc.measureCount,
      noteCount: canonical.size,
    };
  }

  get revisionId(): string {
    return this._revisionId;
  }

  get meta(): ScoreDocumentMeta {
    return this._meta;
  }

  get editVersion(): number {
    return this.editCounter;
  }

  musicXml(view: PitchViewSetting): string {
    const base = view === "hornF" ? this.hornXml : this.concertXml;
    return applyNoteEdits(base, this.edits);
  }

  reviewIssues(): readonly ScoreReviewIssue[] {
    return this.issues.map((issue) => {
      const decided = this.decisions.get(issue.id);
      return decided !== undefined ? { ...issue, status: decided } : issue;
    });
  }

  recordReviewDecision(issueId: string, status: ReviewIssueStatus): void {
    this.decisions.set(issueId, status);
    this.editCounter += 1;
  }

  noteEdits(): ReadonlyMap<string, ScoreNoteEdit> {
    return this.edits;
  }

  setNoteEdit(canonicalId: string, edit: ScoreNoteEdit | null): void {
    if (edit == null || isEmptyNoteEdit(edit)) this.edits.delete(canonicalId);
    else this.edits.set(canonicalId, edit);
    this.editCounter += 1;
  }

  /* ---- #115: engine rhythm edits swap content in place ---- */

  canonicalDocument(): unknown | null {
    return this.canonicalDoc;
  }

  contentSnapshot() {
    return {
      concertXml: this.concertXml,
      hornXml: this.hornXml,
      revisionId: this._revisionId,
      canonicalDocument: this.canonicalDoc,
    };
  }

  /** Swap XML bodies + revision + canonical payload in place. Meta is
   *  recomputed from the new concert XML (measure/note counts can move).
   *  Note edits and review decisions survive — canonical ids are stable,
   *  and the session's undo stack keeps working across the swap. */
  replaceContent(next: {
    concertXml: string;
    hornXml: string;
    revisionId: string;
    canonicalDocument: unknown;
  }): void {
    this.concertXml = next.concertXml;
    this.hornXml = next.hornXml;
    this._revisionId = next.revisionId;
    this.canonicalDoc = next.canonicalDocument;
    this._meta = XmlScoreDocument.computeMeta(next.concertXml);
    this.editCounter += 1;
  }
}

/** Fields extracted from a completed transcription job's `result`. */
export interface EngineScoreDocumentInput {
  readonly concertXml: string;
  readonly hornXml: string;
  readonly revisionId: string;
  readonly issues: readonly ScoreReviewIssue[];
  /** #115: canonical scoreDocument dict from the job result. */
  readonly canonicalDocument?: unknown;
}

/**
 * Build the score document for a real transcription result. Returns
 * `null` when the payload is not usable (missing/invalid MusicXML) so
 * the caller can fall back honestly instead of mounting a broken score.
 */
export function createEngineScoreDocument(
  input: EngineScoreDocumentInput,
): ScoreDocumentPort | null {
  if (!input.concertXml || !input.hornXml) return null;
  try {
    return new XmlScoreDocument({
      concertXml: input.concertXml,
      hornXml: input.hornXml,
      revisionId: input.revisionId,
      issues: input.issues,
      canonicalDocument: input.canonicalDocument,
    });
  } catch {
    // parseScoreDoc throws on malformed MusicXML — a corrupt engine
    // payload must not take down the workspace.
    return null;
  }
}

/**
 * Extract the document input from `session.lastResult` (the completed
 * job's `result` payload). Returns `null` when the result carries no
 * MusicXML — e.g. the mock port's stand-in result — so callers fall
 * back to the fixture document in dev sessions.
 */
export function engineDocumentFromResult(
  result: unknown,
): EngineScoreDocumentInput | null {
  if (typeof result !== "object" || result === null) return null;
  const r = result as Record<string, unknown>;
  const concert = r.musicXmlConcert;
  const horn = r.musicXmlHornF;
  if (typeof concert !== "string" || typeof horn !== "string") return null;
  return {
    concertXml: concert,
    hornXml: horn,
    revisionId:
      typeof r.scoreRevision === "string" ? r.scoreRevision : "rev-engine",
    issues: [],
    canonicalDocument:
      typeof r.scoreDocument === "object" && r.scoreDocument !== null
        ? r.scoreDocument
        : undefined,
  };
}

/**
 * TranscriptionSession — the app-facing engine/job state machine
 * (GUI_UX_SPEC §5, §27; ADR-0002 failure model).
 *
 * One job at a time (the worker enforces `maxConcurrentJobs: 1`).
 * The session owns a {@link SidecarClient} built on a port factory, so a
 * crashed worker can be replaced by a fresh spawn without restarting the
 * UI — restart is an explicit recovery action, never silent resubmission.
 *
 * State is exposed as an immutable {@link SessionSnapshot} via
 * `subscribe()` — React consumes it through a single `useEffect`, and the
 * §27 screen machine maps it to `transcribing` / `transcriptionError` /
 * `scoreReady` / `audioReady`.
 */

import { SidecarClient, type SidecarClientOptions } from "./client";
import {
  ERR,
  SidecarError,
  type EngineCapabilities,
  type EngineInfo,
  type JobEventPayload,
  type JobStartResult,
} from "./protocol";
import type { SidecarPort } from "./port";
import {
  createJobView,
  markCancelling,
  markJobDead,
  reduceJobEvent,
  type JobView,
} from "./jobView";
import { extractReviewIssueCount } from "./review";

/** Real transcription job kind; the spike worker only knows
 *  `demoLongTask`, so the session falls back to it when `transcription`
 *  is not in `capabilities.jobKinds` — documented as the UI-002→UI-040
 *  bridge until the engine ships the real kind. */
export const TRANSCRIPTION_JOB_KIND = "transcription";
export const FALLBACK_JOB_KIND = "demoLongTask";

export type EngineStatus =
  /** No client yet (never started, or torn down). */
  | "offline"
  /** Spawn + handshake in flight. */
  | "starting"
  /** Handshake done — the engine can accept jobs. */
  | "ready"
  /** Worker exited unexpectedly (crash). Restart is an explicit action. */
  | "crashed"
  /** Watchdog: worker stopped answering mid-job. */
  | "unresponsive"
  /** Graceful shutdown completed. */
  | "closed";

/**
 * The failure classes the §20 error surfaces distinguish:
 * - `transcriptionFailed` — the job ended in a terminal `failed` event
 *   while the engine stayed alive → 再試行 is meaningful.
 * - `workerCrashed` — the process died mid-job → エンジンを再起動.
 * - `workerNotResponding` — watchdog probe timed out → エンジンを再起動.
 */
export type FailureKind =
  | "transcriptionFailed"
  | "workerCrashed"
  | "workerNotResponding";

export interface SessionFailure {
  kind: FailureKind;
  /** Machine-readable detail for the diagnostics surface — codes and
   *  engine messages stay OUT of normal UI copy (JAPANESE_UI_COPY §7). */
  detail: string;
  errorCode?: string;
}

export interface SessionSnapshot {
  engine: EngineStatus;
  engineInfo: EngineInfo | null;
  capabilities: EngineCapabilities | null;
  /** In-flight or just-ended job — null when idle. */
  job: JobView | null;
  /** Set on terminal failure; cleared on retry/restart/dismiss. */
  failure: SessionFailure | null;
  /**
   * The `completed` event's `result` payload — the score-data handoff
   * point. UI-030's adapter consumes this to build the canonical score
   * view; UI-040 only guarantees it is preserved verbatim and never
   * mutated by the progress layer.
   */
  lastResult: unknown;
  /** Count of open review issues in `lastResult` (0 when none). */
  reviewIssueCount: number;
  /** Recent supervision diagnostics (stderr + client notes). Ring buffer. */
  diagnostics: readonly string[];
}

type Listener = (snapshot: SessionSnapshot) => void;

export interface TranscriptionSessionOptions {
  portFactory: () => SidecarPort;
  clientOptions?: SidecarClientOptions;
  /** Max retained diagnostic lines. */
  diagnosticLogLimit?: number;
  /** Wall clock — injectable for tests. */
  now?: () => number;
}

const DEFAULT_DIAGNOSTIC_LIMIT = 80;

export class TranscriptionSession {
  private readonly portFactory: () => SidecarPort;
  private readonly clientOptions?: SidecarClientOptions;
  private readonly logLimit: number;
  private readonly now: () => number;
  private client: SidecarClient | null = null;
  private readonly listeners = new Set<Listener>();
  private snap: SessionSnapshot = {
    engine: "offline",
    engineInfo: null,
    capabilities: null,
    job: null,
    failure: null,
    lastResult: null,
    reviewIssueCount: 0,
    diagnostics: [],
  };
  private logLines: string[] = [];

  constructor(opts: TranscriptionSessionOptions) {
    this.portFactory = opts.portFactory;
    this.clientOptions = opts.clientOptions;
    this.logLimit = opts.diagnosticLogLimit ?? DEFAULT_DIAGNOSTIC_LIMIT;
    this.now = opts.now ?? (() => Date.now());
  }

  // ---- subscription -------------------------------------------------------

  getSnapshot(): SessionSnapshot {
    return this.snap;
  }

  subscribe(cb: Listener): () => void {
    this.listeners.add(cb);
    return () => this.listeners.delete(cb);
  }

  private update(patch: Partial<SessionSnapshot>): void {
    this.snap = { ...this.snap, ...patch };
    for (const cb of [...this.listeners]) cb(this.snap);
  }

  private log(line: string): void {
    this.logLines = [...this.logLines.slice(-(this.logLimit - 1)), line];
    this.update({ diagnostics: this.logLines });
  }

  // ---- engine lifecycle ------------------------------------------------------

  private buildClient(): SidecarClient {
    const client = new SidecarClient(this.portFactory(), this.clientOptions);
    client.onJobEvent((e) => this.onJobEvent(e));
    client.onStateChange((s) => this.onClientState(s));
    client.onDiagnostic((l) => this.log(l));
    return client;
  }

  /** Lazily spawn + handshake. Idempotent while `ready`. */
  private async ensureEngine(): Promise<void> {
    if (this.client && this.snap.engine === "ready") return;
    this.update({ engine: "starting" });
    const client = this.buildClient();
    this.client = client;
    try {
      const hs = await client.start();
      this.update({
        engine: "ready",
        engineInfo: hs.engineInfo,
        capabilities: hs.capabilities,
      });
    } catch (e) {
      // Spawn/handshake failure → the engine is down, the error surface
      // offers エンジンを再起動 (which builds a fresh port+client).
      this.update({
        engine: "crashed",
        failure: {
          kind: "workerNotResponding",
          detail: e instanceof Error ? e.message : String(e),
          errorCode: e instanceof SidecarError ? e.code : undefined,
        },
      });
      throw e;
    }
  }

  /**
   * エンジンを再起動 — the crash/unresponsive recovery action (§20).
   * Tears down the old client (best-effort shutdown, then kill) and runs
   * a fresh spawn + handshake. Never resubmits a job.
   */
  async restartEngine(): Promise<void> {
    const old = this.client;
    this.client = null;
    if (old) {
      old.shutdown(800).catch(() => undefined);
    }
    this.update({ engine: "starting", failure: null });
    const client = this.buildClient();
    this.client = client;
    try {
      const hs = await client.start();
      this.update({
        engine: "ready",
        engineInfo: hs.engineInfo,
        capabilities: hs.capabilities,
      });
    } catch (e) {
      this.update({
        engine: "crashed",
        failure: {
          kind: "workerNotResponding",
          detail: e instanceof Error ? e.message : String(e),
          errorCode: e instanceof SidecarError ? e.code : undefined,
        },
      });
      throw e;
    }
  }

  /** Graceful teardown for app shutdown — never throws. */
  async dispose(): Promise<void> {
    const client = this.client;
    this.client = null;
    if (client) await client.shutdown();
    this.update({ engine: "closed" });
  }

  /**
   * `project.save` (#100): persist a .hornscribe.json document through
   * the engine. Spawns the engine lazily when it is not already up —
   * the same engine that produced the score normally still serves.
   */
  async saveProject(path: string, project: unknown): Promise<{ path: string; projectId: string }> {
    await this.ensureEngine();
    const client = this.client;
    if (!client) {
      throw new SidecarError(ERR.ENGINE_UNAVAILABLE, "no engine client");
    }
    return client.call<{ path: string; projectId: string }>(
      "project.save",
      { path, project },
    );
  }

  /**
   * `score.edit` (#115, spec 13): apply one rhythm edit (setDuration /
   * shiftOnset / toggleTie) against the canonical scoreDocument. Returns
   * the rebuilt payload + fresh concert/horn MusicXML + the new
   * content-derived scoreRevision. The engine worker is the same one
   * that produced the score — the call reuses the live client and only
   * spawns lazily when the engine is down.
   */
  async applyScoreEdit(
    scoreDocument: unknown,
    edit: unknown,
  ): Promise<{
    scoreDocument: unknown;
    scoreRevision: string;
    musicXmlConcert: string;
    musicXmlHornF: string;
  }> {
    await this.ensureEngine();
    const client = this.client;
    if (!client) {
      throw new SidecarError(ERR.ENGINE_UNAVAILABLE, "no engine client");
    }
    return client.call<{
      scoreDocument: unknown;
      scoreRevision: string;
      musicXmlConcert: string;
      musicXmlHornF: string;
    }>("score.edit", { scoreDocument, edit });
  }

  // ---- jobs --------------------------------------------------------------------

  /** The jobKind to request: `transcription` when the engine advertises
   *  it, else the spike stand-in (documented bridge). */
  private transcriptionJobKind(): string {
    const kinds = this.snap.capabilities?.jobKinds;
    if (Array.isArray(kinds) && kinds.includes(TRANSCRIPTION_JOB_KIND)) {
      return TRANSCRIPTION_JOB_KIND;
    }
    return FALLBACK_JOB_KIND;
  }

  /**
   * `score.transcribe` → `job.start`. Explicit user action only — retry is
   * never silent (issue rule). Resolves once the job is accepted; progress
   * arrives as job.event frames afterwards.
   */
  async startTranscription(params: unknown = {}): Promise<void> {
    if (this.snap.job && !isSettled(this.snap.job)) {
      throw new SidecarError(ERR.JOB_ALREADY_RUNNING, "a job is already running");
    }
    this.update({ failure: null, lastResult: null, reviewIssueCount: 0 });
    await this.ensureEngine();
    const client = this.client;
    if (!client) {
      throw new SidecarError(ERR.ENGINE_UNAVAILABLE, "no engine client");
    }
    const kind = this.transcriptionJobKind();
    let accepted: JobStartResult;
    try {
      accepted = await client.startJob(kind, params);
    } catch (e) {
      // job.start itself was rejected (request timeout, INVALID_PARAMS, a
      // racing JOB_ALREADY_RUNNING). Surface an honest failure rather than
      // leaving the screen on a job that never existed — unless crash
      // supervision already set a stronger one (don't downgrade it).
      if (!this.snap.failure) {
        this.update({
          failure: {
            kind: "transcriptionFailed",
            detail: e instanceof Error ? e.message : String(e),
            errorCode: e instanceof SidecarError ? e.code : undefined,
          },
        });
      }
      throw e;
    }
    this.update({
      job: createJobView(accepted.jobId, kind, this.now()),
    });
  }

  /**
   * `job.cancel` — cooperative (PROTOCOL.md): the job ends in a terminal
   * `cancelled` event at the next checkpoint, so this resolves while the
   * job is still finishing. The UI shows the honest `cancelling` state
   * until the terminal event arrives.
   */
  async cancelTranscription(): Promise<void> {
    const job = this.snap.job;
    const client = this.client;
    if (!job || isSettled(job) || !client) return;
    if (job.phase === "cancelling") return;
    this.update({ job: markCancelling(job) });
    try {
      await client.cancelJob(job.jobId);
    } catch (e) {
      if (e instanceof SidecarError && e.code === ERR.JOB_NOT_FOUND) {
        // The job already reached a terminal event — fine, it wins.
        return;
      }
      // The cancel request itself failed — restore the honest running
      // state so the button does not lie about a pending cancel. Fold the
      // flag back onto the CURRENT view so progress/stage events that
      // arrived in the meantime are not lost.
      const current = this.snap.job;
      if (
        current &&
        current.jobId === job.jobId &&
        current.phase === "cancelling"
      ) {
        this.update({ job: { ...current, phase: "running" } });
      }
      throw e;
    }
  }

  // ---- event/state handling ----------------------------------------------------

  private onJobEvent(event: JobEventPayload): void {
    const job = this.snap.job;
    if (!job || event.jobId !== job.jobId) return;
    const next = reduceJobEvent(job, event);
    const patch: Partial<SessionSnapshot> = { job: next };
    if (next.phase === "completed") {
      patch.lastResult = next.result;
      patch.reviewIssueCount = extractReviewIssueCount(next.result);
    } else if (next.phase === "failed" && next.error) {
      // Engine stayed alive, the job failed → 再試行 surface.
      patch.failure = {
        kind: "transcriptionFailed",
        detail: `${next.error.code}: ${next.error.message}`,
        errorCode: next.error.code,
      };
    }
    this.update(patch);
  }

  private onClientState(state: string): void {
    switch (state) {
      case "ready":
        this.update({ engine: "ready" });
        break;
      case "starting":
        this.update({ engine: "starting" });
        break;
      case "closed":
        this.update({ engine: "closed" });
        break;
      case "crashed":
      case "unresponsive": {
        const engine = state as EngineStatus;
        const kind: FailureKind =
          state === "crashed" ? "workerCrashed" : "workerNotResponding";
        const code =
          state === "crashed" ? ERR.WORKER_CRASHED : ERR.WORKER_UNRESPONSIVE;
        const job = this.snap.job;
        const patch: Partial<SessionSnapshot> = { engine };
        // ADR-0002: an in-flight job gets NO terminal event from a dead
        // worker — the supervisor marks it failed explicitly.
        if (job && !isSettled(job)) {
          patch.job = markJobDead(job, {
            code,
            message:
              state === "crashed"
                ? "worker process exited while the job was in flight"
                : "worker did not answer the watchdog probe",
          });
          patch.failure = { kind, detail: code, errorCode: code };
        } else if (this.snap.engine === "ready" || this.snap.engine === "starting") {
          // Idle-engine death is reported through `engine` alone — the
          // status bar shows it; no modal error for a silent worker.
        }
        this.update(patch);
        break;
      }
    }
  }

  // ---- terminal bookkeeping ------------------------------------------------------

  /**
   * Clear the settled job record after the UI has consumed the terminal
   * state (completed → scoreReady handoff, cancelled → audioReady). The
   * `lastResult` handoff payload is preserved.
   */
  clearJob(): void {
    const job = this.snap.job;
    if (job && isSettled(job)) this.update({ job: null });
  }

  /** Dismiss the failure surface — the workspace returns to its prior
   *  valid state (audio stays loaded, a prior score is never destroyed). */
  clearFailure(): void {
    if (this.snap.failure) this.update({ failure: null });
  }

  /** Diagnostics text for the 診断情報 dialog (GUI_UX_SPEC §19 fields the
   *  session can honestly report; tool checks belong to UI-060). */
  buildDiagnostics(): string {
    const s = this.snap;
    const lines: string[] = [
      "HornScribe desktop — transcription session",
      `protocolVersion: 1`,
      `engine: ${s.engine}`,
      `engineInfo: ${s.engineInfo ? JSON.stringify(s.engineInfo) : "(none)"}`,
      `jobKinds: ${JSON.stringify(s.capabilities?.jobKinds ?? [])}`,
      `cooperativeCancel: ${String(s.capabilities?.cooperativeCancel ?? "?")}`,
      `cancellationFallback: ${String(s.capabilities?.cancellationFallback ?? "?")}`,
      `job: ${s.job ? `${s.job.jobId} ${s.job.phase}` : "(none)"}`,
      `failure: ${s.failure ? `${s.failure.kind} (${s.failure.detail})` : "(none)"}`,
      "— recent engine diagnostics —",
      ...s.diagnostics.slice(-30),
    ];
    return lines.join("\n");
  }
}

function isSettled(job: JobView): boolean {
  return (
    job.phase === "completed" ||
    job.phase === "cancelled" ||
    job.phase === "failed"
  );
}

"""Score-level rhythm edits on the canonical payload (#115, spec 13).

The simple note edits (pitch shift, delete/restore, enharmonic respell)
are MusicXML-level rewrites the desktop applies client-side. The three
remaining §13 edits change *timing*, so they must re-realize notation:

* ``setDuration`` — a new written duration for one canonical note;
* ``shiftOnset`` — move a note by whole minimum-grid steps;
* ``toggleTie`` — tie/untie a note to the contiguous next same-pitch
  note (a flag pair on the canonical notes; atoms are untouched).

Timing edits rebuild the smallest measure-aligned window containing
the note's old and new spans: notes inside are re-decomposed through
the same :class:`SpanRealizer` the quantizer used, gaps become rests,
and the monophonic contract is re-applied (a note may never cross the
next onset — an edit that would is rejected, not silently clipped).
"""

from __future__ import annotations

from dataclasses import dataclass, replace
from fractions import Fraction
from typing import Any

from hornscribe.domain.ids import RawNoteEventId, ScoreNoteId
from hornscribe.domain.score import (
    MeasureSpan,
    Part,
    QuantizedNote,
    ScoreAtom,
    ScoreDocument,
    ScoreRest,
    ScoreRevisionPayload,
    beat_ql_of,
    measure_spans,
)
from hornscribe.rhythm.contracts import NormalizedNote, RhythmAtom
from hornscribe.rhythm.meter import MeterMap, MeterSegment
from hornscribe.rhythm.profile import QuantizationProfile
from hornscribe.rhythm.realize import SpanRealizer
from hornscribe.rhythm.triplet import (
    TripletRegion,
    enabled_triplet_regions,
    region_evidence,
)

from .options import _PROFILES, _TRIPLET_POLICIES


class ScoreEditError(ValueError):
    """An edit that cannot be applied honestly (mapped to INVALID_PARAMS)."""


@dataclass(frozen=True)
class ScoreEdit:
    """One rhythm edit against the canonical payload.

    ``kind``: ``"setDuration"`` | ``"shiftOnset"`` | ``"toggleTie"``.
    ``noteId``: canonical ``sn-*`` id. ``durationBeats`` is the new
    written length for setDuration; ``steps`` is the signed grid-step
    count for shiftOnset (one step = min_note_value_ql).
    """

    kind: str
    note_id: ScoreNoteId
    duration_beats: Fraction | None = None
    steps: int = 0

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> ScoreEdit:
        kind = data.get("kind")
        if kind not in ("setDuration", "shiftOnset", "toggleTie"):
            raise ScoreEditError(
                f"edit.kind must be setDuration/shiftOnset/toggleTie, got {kind!r}"
            )
        note_id = data.get("noteId")
        if not isinstance(note_id, str) or not note_id:
            raise ScoreEditError("edit.noteId must be a non-empty string")
        duration = data.get("durationBeats")
        try:
            duration_beats = (
                Fraction(duration) if duration is not None else None
            )
            if isinstance(duration, bool):
                raise ValueError("bool")
        except (TypeError, ValueError, ZeroDivisionError) as exc:
            raise ScoreEditError(
                f"edit.durationBeats is not a rational number: {duration!r}"
            ) from exc
        steps = data.get("steps", 0)
        if not isinstance(steps, int) or isinstance(steps, bool):
            raise ScoreEditError(f"edit.steps must be an int, got {steps!r}")
        return cls(
            kind=kind,
            note_id=ScoreNoteId(note_id),
            duration_beats=duration_beats,
            steps=steps,
        )


def _profile_from_settings(settings: dict[str, Any]) -> QuantizationProfile:
    """Rebuild the quantization profile the payload was produced with."""
    kind = settings.get("simplicity", "standard")
    factory = _PROFILES.get(kind, QuantizationProfile.standard)
    base = factory()
    min_dur = settings.get("minDurationQl", "1/4")
    triplets = settings.get("triplets", "auto")
    return replace(
        base,
        min_note_value_ql=Fraction(min_dur),
        triplet_policy=_TRIPLET_POLICIES.get(triplets, base.triplet_policy),
    )


def _meter_map_from_payload(payload: ScoreRevisionPayload) -> MeterMap:
    """Rebuild the meter map the payload's measure layout derives from."""
    beat_ql = beat_ql_of(payload)
    if payload.meter_changes:
        segments = tuple(
            MeterSegment(
                start_ql=c.start_beat * beat_ql,
                numerator=c.time_signature.beats_per_measure,
                denominator=c.time_signature.beat_unit,
                measure_phase_ql=c.measure_phase_beats * beat_ql,
            )
            for c in payload.meter_changes
        )
        return MeterMap(segments)
    ts = payload.time_signature
    measure_len = Fraction(ts.beats_per_measure * 4, ts.beat_unit)
    pickup_ql = payload.pickup_beats * beat_ql
    phase = (measure_len - pickup_ql) % measure_len if pickup_ql else Fraction(0)
    return MeterMap(
        (
            MeterSegment(
                start_ql=Fraction(0),
                numerator=ts.beats_per_measure,
                denominator=ts.beat_unit,
                measure_phase_ql=phase,
            ),
        )
    )


def _triplet_regions(
    notes: tuple[QuantizedNote, ...],
    meter_map: MeterMap,
    profile: QuantizationProfile,
    beat_ql: Fraction,
) -> tuple[TripletRegion, ...]:
    """Recompute the evidence-gated triplet regions for the edited notes."""
    normalized = tuple(
        NormalizedNote(
            source_id=n.source_event_ids[0]
            if n.source_event_ids
            else RawNoteEventId(str(n.id)),
            pitch_midi=n.pitch_midi,
            onset_ql=float(n.start_beat * beat_ql),
            offset_ql=float(n.end_beat * beat_ql),
        )
        for n in notes
    )
    if not normalized:
        return ()
    return enabled_triplet_regions(
        region_evidence(normalized, meter_map, profile), profile
    )


def _find_note(part: Part, note_id: ScoreNoteId) -> int:
    for i, n in enumerate(part.notes):
        if n.id == note_id:
            return i
    raise ScoreEditError(f"note {note_id} not found in the score")


def _clip_overlaps(
    notes: list[QuantizedNote], *, edited_index: int
) -> list[QuantizedNote]:
    """Re-apply the monophonic contract inside the edit window.

    An earlier note may never cross the next onset — it clips. The
    *edited* note is the exception: crossing the next onset is a user
    error (the requested span simply does not fit), so it raises rather
    than silently shortening the user's request.
    """
    out: list[QuantizedNote] = []
    for note in notes:
        if out:
            prev = out[-1]
            if prev.end_beat > note.start_beat:
                if len(out) - 1 == edited_index:
                    # The edited note may never be clipped — the user
                    # asked for a span that does not fit; say so instead
                    # of silently shortening their request.
                    raise ScoreEditError(
                        "the requested span extends past the next "
                        "note's onset"
                    )
                clipped = note.start_beat - prev.start_beat
                if clipped <= 0:
                    raise ScoreEditError(
                        f"note {prev.id} would vanish under the edit"
                    )
                out[-1] = replace(prev, duration_beats=clipped)
        out.append(note)
    # Forward check for the edited note: its end may not cross the next
    # onset (the user asked for a span that does not fit).
    idx = edited_index
    if idx + 1 < len(out) and out[idx].end_beat > out[idx + 1].start_beat:
        raise ScoreEditError(
            "the requested span extends past the next note's onset"
        )
    return out


def _tuplet_group_starts(atoms: list[RhythmAtom]) -> list[bool]:
    """Mark the first atom of each consecutive tuplet run (scorebuild)."""
    flags: list[bool] = []
    in_group = False
    for atom in atoms:
        if atom.tuplet is not None and not in_group:
            flags.append(True)
            in_group = True
        else:
            flags.append(False)
            in_group = atom.tuplet is not None
    return flags


def _atom_to_score(
    atom: RhythmAtom, beat_ql: Fraction, group_start: bool
) -> ScoreAtom:
    return ScoreAtom(
        duration_beats=atom.duration_ql / beat_ql,
        symbol=atom.symbol,
        dots=atom.dots,
        tuplet=atom.tuplet,
        tuplet_group_start=group_start,
        tie_to_next=atom.tie_to_next,
    )


def _retile_window(
    window_notes: list[QuantizedNote],
    lo: Fraction,
    hi: Fraction,
    realizer: SpanRealizer,
    beat_ql: Fraction,
) -> tuple[list[QuantizedNote], list[ScoreRest]]:
    """Re-decompose notes + rest gaps inside the edit window.

    The merged atom stream (notes + rests in onset order) gets tuplet
    group flags across the window — mirrors build_score's flow so a
    group still brackets correctly. Window bounds are measure edges,
    so tie/atom structure never crosses the splice.
    """
    events: list[tuple[Fraction, str, int]] = [
        (n.start_beat, "note", i) for i, n in enumerate(window_notes)
    ]
    gaps: list[tuple[Fraction, Fraction]] = []
    # Gaps tile the whole window — including the edges, where the
    # measure's content may not reach the barline (a shortened note
    # leaves a rest behind it).
    cursor = lo
    for n in sorted(window_notes, key=lambda n: n.start_beat):
        if n.start_beat > cursor:
            gaps.append((cursor, n.start_beat))
        cursor = max(cursor, n.end_beat)
    if cursor < hi:
        gaps.append((cursor, hi))
    events += [(g[0], "rest", i) for i, g in enumerate(gaps)]
    events.sort(key=lambda e: e[0])

    stream: list[RhythmAtom] = []
    note_ranges: list[tuple[int, int]] = [(0, 0)] * len(window_notes)
    rest_ranges: list[tuple[int, int]] = [(0, 0)] * len(gaps)
    for _pos, kind, i in events:
        if kind == "note":
            n = window_notes[i]
            notation = realizer.realize_span(
                n.start_beat * beat_ql, n.end_beat * beat_ql, is_rest=False
            ).notation
            atoms = notation.atoms if notation is not None else ()
            start = len(stream)
            stream.extend(atoms)
            note_ranges[i] = (start, len(stream))
        else:
            s, e = gaps[i]
            rest_notation = realizer.rest_span(s * beat_ql, e * beat_ql)
            atoms = rest_notation.atoms if rest_notation is not None else ()
            start = len(stream)
            stream.extend(atoms)
            rest_ranges[i] = (start, len(stream))
    flags = _tuplet_group_starts(stream)

    new_notes = [
        replace(
            n,
            atoms=tuple(
                _atom_to_score(a, beat_ql, flags[lo + j])
                for j, a in enumerate(stream[lo:hi])
            ),
        )
        for n, (lo, hi) in zip(window_notes, note_ranges, strict=True)
    ]
    new_rests = [
        ScoreRest(
            start_beat=gaps[i][0],
            atoms=tuple(
                _atom_to_score(a, beat_ql, flags[lo + j])
                for j, a in enumerate(stream[lo:hi])
            ),
        )
        for i, (lo, hi) in enumerate(rest_ranges)
        if lo < hi
    ]
    return (new_notes, new_rests)


def _expand_window(
    notes: tuple[QuantizedNote, ...],
    spans: tuple[MeasureSpan, ...],
    lo: Fraction,
    hi: Fraction,
) -> tuple[Fraction, Fraction]:
    """Grow ``[lo, hi)`` to whole measures covering every intersecting note."""
    for n in notes:
        if n.start_beat < hi and n.end_beat > lo:
            lo = min(lo, n.start_beat)
            hi = max(hi, n.end_beat)
    for span in spans:
        if span.start_beat < hi and span.end_beat > lo:
            lo = min(lo, span.start_beat)
            hi = max(hi, span.end_beat)
    return (lo, hi)


def _apply_timing_edit(
    payload: ScoreRevisionPayload,
    part_index: int,
    note_index: int,
    new_start: Fraction | None,
    new_duration: Fraction | None,
) -> Part:
    """Rebuild the part after a timing edit (setDuration/shiftOnset)."""
    part = payload.parts[part_index]
    beat_ql = beat_ql_of(payload)
    notes = list(part.notes)
    target = notes[note_index]
    start = new_start if new_start is not None else target.start_beat
    duration = (
        new_duration if new_duration is not None else target.duration_beats
    )
    if duration <= 0:
        raise ScoreEditError("duration must be positive")
    if start < 0:
        raise ScoreEditError("the note cannot start before the score")
    notes[note_index] = replace(
        target, start_beat=start, duration_beats=duration
    )
    notes.sort(key=lambda n: (n.start_beat, n.id))
    edited_index = next(i for i, n in enumerate(notes) if n.id == target.id)
    notes = _clip_overlaps(notes, edited_index=edited_index)

    # The rebuild window: every measure touching the union of old and
    # new spans, grown to cover notes straddling its edges.
    spans = measure_spans(payload)
    lo = min(target.start_beat, start)
    hi = max(target.end_beat, start + duration)
    prev = None
    while (lo, hi) != prev:
        prev = (lo, hi)
        lo, hi = _expand_window(tuple(notes), spans, lo, hi)
    window_notes = [
        n for n in notes if n.start_beat < hi and n.end_beat > lo
    ]

    profile = _profile_from_settings(payload.quantization_settings)
    meter_map = _meter_map_from_payload(payload)
    regions = _triplet_regions(tuple(notes), meter_map, profile, beat_ql)
    realizer = SpanRealizer(meter_map, profile, triplet_regions=regions)
    try:
        new_window, new_rests = _retile_window(
            window_notes, lo, hi, realizer, beat_ql
        )
    except ValueError as exc:
        raise ScoreEditError(
            f"the edited rhythm cannot be written in this meter: {exc}"
        ) from exc
    window_ids = {n.id for n in window_notes}
    final_notes = tuple(
        n if n.id not in window_ids else next(
            w for w in new_window if w.id == n.id
        )
        for n in notes
    )
    kept_rests = [
        r for r in part.rests if r.end_beat <= lo or r.start_beat >= hi
    ]
    return replace(
        part,
        notes=final_notes,
        rests=tuple(sorted(kept_rests + new_rests, key=lambda r: r.start_beat)),
    )


def _apply_tie_toggle(
    payload: ScoreRevisionPayload,
    part_index: int,
    note_index: int,
) -> Part:
    """Flip the tie between a note and the contiguous next same-pitch note."""
    part = payload.parts[part_index]
    notes = list(part.notes)
    if note_index + 1 >= len(notes):
        raise ScoreEditError("there is no next note to tie to")
    cur = notes[note_index]
    nxt = notes[note_index + 1]
    tied = cur.tie_start and nxt.tie_stop
    if tied:
        notes[note_index] = replace(cur, tie_start=False)
        notes[note_index + 1] = replace(nxt, tie_stop=False)
        return replace(part, notes=tuple(notes))
    if cur.pitch_midi != nxt.pitch_midi:
        raise ScoreEditError("a tie needs the same pitch on both notes")
    if cur.end_beat != nxt.start_beat:
        raise ScoreEditError(
            "a tie needs contiguous notes (the next note must start "
            "where this one ends)"
        )
    notes[note_index] = replace(cur, tie_start=True)
    notes[note_index + 1] = replace(nxt, tie_stop=True)
    return replace(part, notes=tuple(notes))


def apply_score_edit(
    document: ScoreDocument, edit: ScoreEdit
) -> ScoreDocument:
    """Apply one §13 rhythm edit and return the rebuilt document.

    The payload's canonical notes keep their ids — review issues and
    client-side note edits stay attached. A new score revision falls
    out of the changed content automatically (content-derived ids).
    """
    payload = document.payload
    beat_ql = beat_ql_of(payload)
    # Locate the note across parts (single-part today, but the loop is
    # free).
    part_index = -1
    note_index = -1
    for pi, part in enumerate(payload.parts):
        try:
            note_index = _find_note(part, edit.note_id)
            part_index = pi
            break
        except ScoreEditError:
            continue
    if part_index < 0:
        raise ScoreEditError(f"note {edit.note_id} not found in the score")
    part = payload.parts[part_index]
    target = part.notes[note_index]

    if edit.kind == "toggleTie":
        new_part = _apply_tie_toggle(payload, part_index, note_index)
    else:
        if edit.kind == "setDuration":
            if edit.duration_beats is None:
                raise ScoreEditError("setDuration requires durationBeats")
            new_start, new_duration = None, edit.duration_beats
        else:  # shiftOnset
            if edit.steps == 0:
                raise ScoreEditError("shiftOnset requires a non-zero steps")
            profile = _profile_from_settings(payload.quantization_settings)
            step_beats = profile.min_note_value_ql / beat_ql
            new_start = target.start_beat + step_beats * edit.steps
            new_duration = None
        new_part = _apply_timing_edit(
            payload, part_index, note_index, new_start, new_duration
        )
    parts = list(payload.parts)
    parts[part_index] = new_part
    new_payload = replace(payload, parts=tuple(parts))
    return replace(document, payload=new_payload)

"""HornScribe engine sidecar worker (UI-002 spike).

Speaks the NDJSON protocol in ``protocol/PROTOCOL.md`` over stdin/stdout:
stdout carries protocol frames only, all diagnostics go to stderr.

Lifecycle contract (ADR-0002):

- requests are dispatched sequentially on the stdin read loop
- jobs run on daemon threads so the loop stays responsive (progress
  events stream while ``engine.ping`` etc. keep answering)
- ``engine.shutdown`` replies, then the worker exits 0
- stdin EOF is an implicit graceful shutdown (also exit 0)
- an incompatible ``engine.handshake`` protocol version is refused with
  ``PROTOCOL_VERSION_MISMATCH`` and the worker exits — it will not serve
  a peer it cannot talk to
- at most one job is in flight (``JOB_ALREADY_RUNNING``); the spike does
  not need a pool before evidence requires it (issue non-goals)
"""

from __future__ import annotations

import argparse
import contextlib
import importlib.util
import logging
import os
import platform
import sys
import threading
import time
from collections.abc import Callable
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, TextIO

import hornscribe
from hornscribe.project.errors import ProjectError
from hornscribe.project.model import (
    PROJECT_FILE_SUFFIX,
    HornScribeProject,
    hash_file_sha256,
)
from hornscribe.project.store import ProjectStore
from hornscribe.transcription import (
    JOB_KIND_TRANSCRIPTION,
    TranscriptionParams,
    run_transcription_job,
)
from hornscribe.worker import protocol
from hornscribe.worker.jobs import (
    JOB_KIND_DEMO_LONG_TASK,
    DemoLongTaskParams,
    run_demo_long_task,
)

# Job kinds this worker accepts. ``transcription`` (ENG-002) is the real
# pipeline; ``demoLongTask`` stays for protocol/regression tests.
SUPPORTED_JOB_KINDS: tuple[str, ...] = (
    JOB_KIND_TRANSCRIPTION,
    JOB_KIND_DEMO_LONG_TASK,
)

log = logging.getLogger("hornscribe.worker")

_SHUTDOWN_JOIN_TIMEOUT_S = 2.0


@dataclass
class _Job:
    """Handle for one in-flight job thread."""

    job_id: str
    kind: str
    cancel: threading.Event
    done: threading.Event = field(default_factory=threading.Event)
    thread: threading.Thread | None = None


class Worker:
    """The sidecar process: sequential requests, threaded jobs."""

    def __init__(self, stdin: TextIO, stdout: TextIO) -> None:
        self._stdin = stdin
        self._stdout = stdout
        self._write_lock = threading.Lock()
        self._shutdown = threading.Event()
        self._exit_after_response = False
        self._job: _Job | None = None
        self._job_counter = 0
        self._started = time.monotonic()
        self._methods: dict[str, Callable[[Any], dict[str, Any]]] = {
            "engine.handshake": self._handle_handshake,
            "engine.ping": self._handle_ping,
            "engine.shutdown": self._handle_shutdown,
            "job.start": self._handle_job_start,
            "job.cancel": self._handle_job_cancel,
            # #100: persist a .hornscribe.json project document (schema
            # v1) — the save path the UI's プロジェクトを保存 command
            # calls. Validation runs through HornScribeProject.from_dict
            # so a malformed document is rejected, never written.
            "project.save": self._handle_project_save,
            # #115 (spec 13): rhythm edits that need re-realization —
            # duration change, onset grid shift, tie toggle. Runs the
            # same SpanRealizer the quantizer used, so the written
            # output stays consistent with the original engraving.
            "score.edit": self._handle_score_edit,
            # Spike-only supervisor test hook: wedges the dispatch loop so
            # the supervisor-side read timeout path can be exercised.
            # Not a stable API; gated on the "debug." prefix.
            "debug.hang": self._handle_debug_hang,
            # Stack dump of every thread (diagnostics for a stalled job).
            "debug.stacks": self._handle_debug_stacks,
        }

    # ---- frame IO -----------------------------------------------------

    def _send(self, envelope: protocol.Envelope) -> None:
        line = protocol.encode_message(envelope)
        with self._write_lock:
            self._stdout.write(line + "\n")
            self._stdout.flush()

    def _respond(self, request_id: str, method: str | None, payload: Any) -> None:
        self._send(protocol.make_response(request_id, method, payload))

    def _respond_error(
        self,
        request_id: str | None,
        method: str | None,
        code: str,
        message: str,
        details: dict[str, Any] | None = None,
    ) -> None:
        self._send(
            protocol.make_error_response(
                request_id, code, message, details=details, method=method
            )
        )

    def _emit_event(self, method: str, payload: dict[str, Any]) -> None:
        self._send(protocol.make_event(method, payload))

    # ---- main loop ----------------------------------------------------

    def serve(self) -> int:
        """Run the read/dispatch loop until shutdown or stdin EOF."""
        log.info(
            "sidecar started pid=%d protocol=v%d hornscribe=%s",
            os.getpid(),
            protocol.PROTOCOL_VERSION,
            hornscribe.__version__,
        )
        while not self._shutdown.is_set():
            line = self._stdin.readline()
            if line == "":
                log.info("stdin EOF; shutting down")
                break
            self._handle_line(line)
            if self._exit_after_response:
                break
        self._shutdown_gracefully()
        log.info("sidecar stopped")
        return 0

    def _shutdown_gracefully(self) -> None:
        job = self._job
        if job is not None and not job.done.is_set():
            log.info("cancelling active job %s for shutdown", job.job_id)
            job.cancel.set()
            if job.thread is not None:
                job.thread.join(timeout=_SHUTDOWN_JOIN_TIMEOUT_S)

    def _handle_line(self, line: str) -> None:
        try:
            msg = protocol.parse_message(line)
        except protocol.ProtocolError as exc:
            log.warning("rejected inbound frame: %s", exc)
            self._respond_error(exc.request_id, None, exc.code, exc.message, exc.details)
            return
        if msg.kind != protocol.KIND_REQUEST:
            # The peer only ever sends requests. Inbound responses/events
            # are logged and dropped — never answered — to avoid any
            # chance of a reply loop.
            log.warning("ignoring inbound %s frame id=%s", msg.kind, msg.id)
            return
        assert msg.id is not None
        assert msg.method is not None
        handler = self._methods.get(msg.method)
        if handler is None:
            self._respond_error(
                msg.id,
                msg.method,
                protocol.ERR_UNKNOWN_METHOD,
                f"unknown method {msg.method!r}",
                details={"methods": sorted(self._methods)},
            )
            return
        try:
            payload = handler(msg.payload)
        except protocol.ProtocolError as exc:
            self._respond_error(msg.id, msg.method, exc.code, exc.message, exc.details)
            return
        except Exception:
            # Errors are structured data, never raw tracebacks (ADR-0002);
            # the traceback stays on stderr where diagnostics belong.
            log.exception("handler failed for %s", msg.method)
            self._respond_error(
                msg.id, msg.method, protocol.ERR_INTERNAL, "internal worker error"
            )
            return
        self._respond(msg.id, msg.method, payload)

    # ---- method handlers ----------------------------------------------

    def _handle_handshake(self, payload: Any) -> dict[str, Any]:
        params = payload if isinstance(payload, dict) else {}
        client_v = params.get("protocolVersion", protocol.PROTOCOL_VERSION)
        if client_v != protocol.PROTOCOL_VERSION:
            # Refuse explicitly, then exit: a worker that cannot speak the
            # peer's version must not limp along (ADR-0002).
            self._exit_after_response = True
            raise protocol.ProtocolError(
                protocol.ERR_PROTOCOL_VERSION_MISMATCH,
                f"client requested protocol v{client_v!r}; "
                f"worker speaks v{protocol.PROTOCOL_VERSION}",
                details={
                    "requested": client_v,
                    "supported": [protocol.PROTOCOL_VERSION],
                },
            )
        return {
            "protocolVersion": protocol.PROTOCOL_VERSION,
            "engineInfo": {
                "name": "hornscribe-engine",
                "version": hornscribe.__version__,
                "python": platform.python_version(),
                "platform": sys.platform,
                "pid": os.getpid(),
            },
            "capabilities": {
                "methods": sorted(self._methods),
                "jobKinds": list(SUPPORTED_JOB_KINDS),
                "maxConcurrentJobs": 1,
                "cooperativeCancel": True,
                "cancellationFallback": "terminate+restart",
                "progressEvents": True,
                "basicPitchAvailable": importlib.util.find_spec("basic_pitch") is not None,
            },
        }

    def _handle_ping(self, payload: Any) -> dict[str, Any]:
        echo = payload.get("echo") if isinstance(payload, dict) else None
        return {
            "echo": echo,
            "workerPid": os.getpid(),
            "uptimeMs": round((time.monotonic() - self._started) * 1000.0, 1),
        }

    def _handle_shutdown(self, payload: Any) -> dict[str, Any]:
        self._exit_after_response = True
        active = self._active_job()
        return {"ok": True, "activeJob": active.job_id if active else None}

    def _handle_job_start(self, payload: Any) -> dict[str, Any]:
        if not isinstance(payload, dict):
            raise protocol.ProtocolError(
                protocol.ERR_INVALID_PARAMS, "job.start payload must be an object"
            )
        kind = payload.get("jobKind")
        if not isinstance(kind, str) or not kind:
            raise protocol.ProtocolError(
                protocol.ERR_INVALID_PARAMS, "job.start requires a string 'jobKind'"
            )
        if kind not in SUPPORTED_JOB_KINDS:
            raise protocol.ProtocolError(
                protocol.ERR_UNKNOWN_JOB_KIND,
                f"unsupported jobKind {kind!r}",
                details={"supported": list(SUPPORTED_JOB_KINDS)},
            )
        active = self._active_job()
        if active is not None:
            raise protocol.ProtocolError(
                protocol.ERR_JOB_ALREADY_RUNNING,
                "a job is already running",
                details={"activeJobId": active.job_id, "maxConcurrentJobs": 1},
            )
        self._job_counter += 1
        job_id = f"job-{self._job_counter:04d}"
        if kind == JOB_KIND_TRANSCRIPTION:
            try:
                tparams = TranscriptionParams.from_payload(payload.get("params"))
            except ValueError as exc:
                raise protocol.ProtocolError(
                    protocol.ERR_INVALID_PARAMS, str(exc)
                ) from exc
            _warm_engine_imports()
            self._job = self._start_transcription_job(job_id, tparams)
        else:
            try:
                params = DemoLongTaskParams.from_payload(payload.get("params"))
            except ValueError as exc:
                raise protocol.ProtocolError(
                    protocol.ERR_INVALID_PARAMS, str(exc)
                ) from exc
            self._job = self._start_demo_job(job_id, params)
        return {"jobId": job_id, "jobKind": kind, "state": "accepted"}

    def _handle_job_cancel(self, payload: Any) -> dict[str, Any]:
        job_id = payload.get("jobId") if isinstance(payload, dict) else None
        if not isinstance(job_id, str) or not job_id:
            raise protocol.ProtocolError(
                protocol.ERR_INVALID_PARAMS, "job.cancel requires a string 'jobId'"
            )
        job = self._job
        if job is None or job.done.is_set() or job.job_id != job_id:
            raise protocol.ProtocolError(
                protocol.ERR_JOB_NOT_FOUND, f"no active job {job_id!r}"
            )
        job.cancel.set()
        return {"jobId": job.job_id, "cancellation": "requested"}

    def _handle_project_save(self, payload: Any) -> dict[str, Any]:
        """`project.save` — write a .hornscribe.json document (#100).

        Payload: ``{"path": str, "project": {...schema v1 dict...}}``.
        The document is validated through HornScribeProject.from_dict
        before anything touches disk; a missing sourceAudio.contentHash
        is computed here so the relink contract stays authoritative.
        Writes go through ProjectStore (atomic tmp+replace + recovery
        snapshot).
        """
        if not isinstance(payload, dict):
            raise protocol.ProtocolError(
                protocol.ERR_INVALID_PARAMS, "project.save payload must be an object"
            )
        path_raw = payload.get("path")
        if not isinstance(path_raw, str) or not path_raw.endswith(PROJECT_FILE_SUFFIX):
            raise protocol.ProtocolError(
                protocol.ERR_INVALID_PARAMS,
                f"project.save requires a path ending in {PROJECT_FILE_SUFFIX}",
            )
        project_data = payload.get("project")
        if not isinstance(project_data, dict):
            raise protocol.ProtocolError(
                protocol.ERR_INVALID_PARAMS, "project.save requires a 'project' object"
            )

        # Fill sourceAudio.contentHash when the caller only knows the
        # path — hashing is authoritative work the engine owns.
        source = project_data.get("sourceAudio")
        if isinstance(source, dict) and not source.get("contentHash"):
            original = source.get("originalPath")
            if isinstance(original, str) and original:
                source_path = Path(original)
                if source_path.is_file():
                    project_data = dict(project_data)
                    project_data["sourceAudio"] = {
                        "originalPath": original,
                        "contentHash": hash_file_sha256(source_path),
                    }

        try:
            project = HornScribeProject.from_dict(project_data)
        except ProjectError as exc:
            raise protocol.ProtocolError(
                protocol.ERR_INVALID_PARAMS, f"invalid project document: {exc}"
            ) from exc

        target = Path(path_raw)
        try:
            ProjectStore(target.parent).save(project, target)
        except OSError as exc:
            raise protocol.ProtocolError(
                protocol.ERR_JOB_FAILED, f"could not write project file: {exc}"
            ) from exc
        return {"path": str(target), "projectId": str(project.project_id)}

    def _handle_score_edit(self, payload: Any) -> dict[str, Any]:
        """`score.edit` — apply one §13 rhythm edit (#115).

        Payload: ``{"scoreDocument": {...}, "edit": {...}}``. Returns the
        rebuilt ``scoreDocument`` plus fresh concert/horn MusicXML and
        the new ``scoreRevision``. The edit kinds (setDuration /
        shiftOnset / toggleTie) re-realize the affected measures through
        the same SpanRealizer the quantizer used — measure length and
        rest/atom structure stay consistent instead of drifting.
        """
        if not isinstance(payload, dict):
            raise protocol.ProtocolError(
                protocol.ERR_INVALID_PARAMS, "score.edit payload must be an object"
            )
        doc_raw = payload.get("scoreDocument")
        if not isinstance(doc_raw, dict):
            raise protocol.ProtocolError(
                protocol.ERR_INVALID_PARAMS,
                "score.edit requires a 'scoreDocument' object",
            )
        edit_raw = payload.get("edit")
        if not isinstance(edit_raw, dict):
            raise protocol.ProtocolError(
                protocol.ERR_INVALID_PARAMS, "score.edit requires an 'edit' object"
            )
        from hornscribe.domain.score import ScoreDocument  # noqa: PLC0415
        from hornscribe.export.musicxml import (  # noqa: PLC0415
            export_concert_musicxml,
            export_horn_in_f_musicxml,
        )
        from hornscribe.transcription.scoreedit import (  # noqa: PLC0415
            ScoreEdit,
            ScoreEditError,
            apply_score_edit,
        )
        try:
            document = ScoreDocument.from_dict(doc_raw)
        except (KeyError, TypeError, ValueError) as exc:
            raise protocol.ProtocolError(
                protocol.ERR_INVALID_PARAMS,
                f"invalid scoreDocument: {exc}",
            ) from exc
        try:
            edit = ScoreEdit.from_dict(edit_raw)
            new_document = apply_score_edit(document, edit)
        except ScoreEditError as exc:
            raise protocol.ProtocolError(
                protocol.ERR_INVALID_PARAMS, str(exc)
            ) from exc
        except (KeyError, TypeError, ValueError) as exc:
            raise protocol.ProtocolError(
                protocol.ERR_JOB_FAILED, f"score edit failed: {exc}"
            ) from exc
        return {
            "scoreDocument": new_document.to_dict(),
            "scoreRevision": str(new_document.revision),
            "musicXmlConcert": export_concert_musicxml(new_document),
            "musicXmlHornF": export_horn_in_f_musicxml(new_document),
        }

    def _handle_debug_hang(self, payload: Any) -> dict[str, Any]:
        seconds = 5.0
        if isinstance(payload, dict):
            raw = payload.get("seconds")
            if isinstance(raw, (int, float)) and not isinstance(raw, bool):
                seconds = float(raw)
        seconds = min(max(seconds, 0.0), 300.0)
        log.warning("debug.hang: wedging dispatch loop for %.1fs", seconds)
        time.sleep(seconds)
        return {"sleptSeconds": seconds}

    def _handle_debug_stacks(self, payload: Any) -> dict[str, Any]:
        """Return a text dump of all thread stacks (job debugging).

        Read-only; used to diagnose a job that appears stuck (e.g. an
        import deadlock in a daemon thread). Not a stable API.
        """
        import traceback

        frames = sys._current_frames()
        out: list[str] = []
        for tid, frame in frames.items():
            out.append(f"--- thread {tid} ---")
            out.extend(traceback.format_stack(frame))
        return {"threads": len(frames), "dump": "".join(out)}

    # ---- jobs ----------------------------------------------------------

    def _active_job(self) -> _Job | None:
        job = self._job
        if job is not None and not job.done.is_set():
            return job
        return None

    def _start_demo_job(self, job_id: str, params: DemoLongTaskParams) -> _Job:
        job = _Job(job_id=job_id, kind=JOB_KIND_DEMO_LONG_TASK, cancel=threading.Event())

        def emit(phase: str, **fields: Any) -> None:
            body: dict[str, Any] = {
                "jobId": job_id,
                "jobKind": JOB_KIND_DEMO_LONG_TASK,
                "phase": phase,
            }
            body.update(fields)
            self._emit_event("job.event", body)

        def run() -> None:
            try:
                run_demo_long_task(
                    job_id=job_id, params=params, emit=emit, cancel=job.cancel
                )
            except Exception:
                log.exception("job %s crashed", job_id)
                emit(
                    "failed",
                    error={
                        "code": protocol.ERR_INTERNAL,
                        "message": "job crashed unexpectedly",
                    },
                )
            finally:
                job.done.set()

        job.thread = threading.Thread(target=run, name=f"{job_id}", daemon=True)
        job.thread.start()
        return job

    def _start_transcription_job(
        self, job_id: str, params: TranscriptionParams
    ) -> _Job:
        job = _Job(
            job_id=job_id, kind=JOB_KIND_TRANSCRIPTION, cancel=threading.Event()
        )

        def emit(phase: str, **fields: Any) -> None:
            body: dict[str, Any] = {
                "jobId": job_id,
                "jobKind": JOB_KIND_TRANSCRIPTION,
                "phase": phase,
            }
            body.update(fields)
            self._emit_event("job.event", body)

        def run() -> None:
            try:
                run_transcription_job(
                    job_id=job_id, params=params, emit=emit, cancel=job.cancel
                )
            except Exception:
                log.exception("job %s crashed", job_id)
                emit(
                    "failed",
                    error={
                        "code": protocol.ERR_INTERNAL,
                        "message": "job crashed unexpectedly",
                    },
                )
            finally:
                job.done.set()

        job.thread = threading.Thread(target=run, name=f"{job_id}", daemon=True)
        job.thread.start()
        return job


def _warm_engine_imports() -> None:
    # Import the native engine stack on the main thread (ENG-002).
    # Loading numpy/onnxruntime DLLs for the first time from a non-main
    # thread can wedge inside create_module on Windows (loader-lock
    # interaction). Importing here — before the job thread starts —
    # makes the job thread hit sys.modules instead. Missing packages
    # are ignored: the job itself reports ENGINE_DEPENDENCY_MISSING
    # with the proper error code.
    # librosa is a lazy_loader package: importing the top level does NOT
    # pull the submodules the pipeline touches, so name them explicitly.
    for name in ("librosa.core.audio", "librosa.beat", "basic_pitch.inference"):
        try:
            importlib.import_module(name)
        except Exception:
            log.debug("engine warm-up import of %s failed", name, exc_info=True)
            break


def _reconfigure_stream(stream: TextIO, **kwargs: Any) -> None:
    """Best-effort ``TextIOWrapper.reconfigure`` (absent on odd streams)."""
    reconfigure = getattr(stream, "reconfigure", None)
    if callable(reconfigure):
        with contextlib.suppress(OSError, ValueError):
            reconfigure(**kwargs)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        prog="hornscribe.worker",
        description="HornScribe engine sidecar (NDJSON over stdio; logs on stderr)",
    )
    parser.add_argument(
        "--version",
        action="version",
        version=(
            f"hornscribe-engine {hornscribe.__version__} "
            f"(protocol v{protocol.PROTOCOL_VERSION})"
        ),
    )
    parser.add_argument(
        "-v",
        "--verbose",
        action="store_true",
        help="debug-level diagnostics on stderr",
    )
    args = parser.parse_args(argv)
    logging.basicConfig(
        stream=sys.stderr,
        level=logging.DEBUG if args.verbose else logging.INFO,
        format="%(asctime)s %(levelname)s %(name)s: %(message)s",
    )
    # stdout is protocol-only: pin UTF-8 + '\n' so a Windows console
    # encoding or newline translation can never corrupt a frame.
    _reconfigure_stream(sys.stdout, encoding="utf-8", newline="\n", write_through=True)
    _reconfigure_stream(sys.stdin, encoding="utf-8")
    return Worker(sys.stdin, sys.stdout).serve()


if __name__ == "__main__":
    raise SystemExit(main())
